from common import *
def balanced(s):
    st=[];pair={')':'(',']':'[','}':'{'}
    for c in s.strip():
        if c in '([{': st.append(c)
        elif not st or st.pop()!=pair[c]: return 'NO'
    return 'NO' if st else 'YES'
